class Solution:
    def validStrings(self, n: int) -> List[str]:
        from collections import deque
        if n == 0:
            return []
        queue = deque(["0", "1"])
        for _ in range(n - 1):
            new_queue = deque()
            for s in queue:
                if s[-1] == "1":
                    new_queue.append(s + "0")
                    new_queue.append(s + "1")
                else:  # s[-1] == "0"
                    new_queue.append(s + "1")
            queue = new_queue
        return list(queue)

class Solution:
    def numberOfAlternatingGroups(self, colors: List[int]) -> int:
        n = len(colors)
        count = 0
        for i in range(n):
            left = (i - 1) % n
            right = (i + 1) % n
            if colors[left] != colors[i] and colors[i] != colors[right]:
                count += 1
        return count

class Solution:
    def getEncryptedString(self, s: str, k: int) -> str:
        n = len(s)
        encrypted_chars = []
        for i in range(n):
            new_index = (i + k) % n
            encrypted_chars.append(s[new_index])
        return ''.join(encrypted_chars)

