class Solution:
    def maxPossibleScore(self, start: List[int], d: int) -> int:
        start.sort()

        def can_choose_with_diff(mid):
            prev = start[0]
            for i in range(1, len(start)):
                required = prev + mid
                if required > start[i] + d:
                    return False
                prev = max(required, start[i])
            return True

        low = 0
        high = (start[-1] + d) - start[0]
        while low <= high:
            mid = (low + high) // 2
            if can_choose_with_diff(mid):
                low = mid + 1
            else:
                high = mid - 1
        return high

