class Solution:
    def minChanges(self, nums: List[int], k: int) -> int:
        n = len(nums)
        count = [0] * (k + 1)

        for i in range(n // 2):
            diff = abs(nums[i] - nums[n - i - 1])
            if diff <= k:
                count[diff] += 1

        max_count = max(count)
        total_pairs = n // 2
        min_changes = total_pairs - max_count

        return min_changes

