class Solution:
    def finalPositionOfSnake(self, n: int, commands: List[str]) -> int:
        row = 0
        col = 0
        for cmd in commands:
            if cmd == "RIGHT":
                col += 1
            elif cmd == "LEFT":
                col -= 1
            elif cmd == "UP":
                row -= 1
            elif cmd == "DOWN":
                row += 1
        cell = (row * n) + col
        return cell

