class Solution:
    def maxScore(self, grid: List[List[int]]) -> int:
        if not grid or not grid[0]:
            return 0

        num_rows = len(grid)
        self.max_sum = 0

        def backtrack(row, selected_values, current_sum):
            if row == num_rows:
                if current_sum > self.max_sum:
                    self.max_sum = current_sum
                return

            # Select a cell from the current row
            for cell in grid[row]:
                if cell not in selected_values:
                    backtrack(row + 1, selected_values | {cell}, current_sum + cell)

            # Skip the current row
            backtrack(row + 1, selected_values, current_sum)

        backtrack(0, frozenset(), 0)
        return self.max_sum

class Solution:
    def countOfSubstrings(self, word: str, k: int) -> int:
        vowels = set('aeiou')
        count = 0
        n = len(word)
        for i in range(n):
            vowel_set = set()
            consonant_count = 0
            for j in range(i, n):
                if word[j] in vowels:
                    vowel_set.add(word[j])
                else:
                    consonant_count += 1
                if consonant_count > k:
                    break
                if consonant_count == k and len(vowel_set) == 5:
                    count += 1
        return count

class Solution:
    def validSubstringCount(self, word1: str, word2: str) -> int:
        from collections import Counter

        freq2 = Counter(word2)
        required = len(freq2)
        deficit = freq2.copy()
        formed = 0
        left = 0
        ans = 0
        n = len(word1)

        for right in range(n):
            char = word1[right]
            if char in deficit:
                deficit[char] -= 1
                if deficit[char] == 0:
                    formed += 1

            while formed == required:
                ans += left + 1  # Count substrings ending at 'right'
                char_left = word1[left]
                if char_left in deficit:
                    deficit[char_left] += 1
                    if deficit[char_left] == 1:
                        formed -= 1
                left += 1

        return ans

class Solution:
    def maxValue(self, nums: List[int], k: int) -> int:
        n = len(nums)
        if k > n // 2:
            return 0  # Not enough elements to form subsequences

        # Compute dp1: dp1[i][or_val] = True if we can select k elements from first i elements with OR or_val
        dp1 = [[False] * 128 for _ in range(n + 1)]
        dp1[0][0] = True
        for i in range(1, n + 1):
            num = nums[i - 1]
            for j in range(k + 1):
                if j < k:
                    for or_val in range(128):
                        if dp1[i - 1][or_val]:
                            dp1[i][or_val | num] = True
                if j > 0:
                    for or_val in range(128):
                        if dp1[i - 1][or_val]:
                            dp1[i][or_val] = True
            if i >= k:
                for or_val in range(128):
                    dp1[i][or_val] = dp1[i][or_val] or dp1[i - 1][or_val]

        # Compute dp2: dp2[i][or_val] = True if we can select k elements from last i elements with OR or_val
        dp2 = [[False] * 128 for _ in range(n + 1)]
        dp2[n][0] = True
        for i in range(n - 1, -1, -1):
            num = nums[i]
            for j in range(k + 1):
                if j < k:
                    for or_val in range(128):
                        if dp2[i + 1][or_val]:
                            dp2[i][or_val | num] = True
                if j > 0:
                    for or_val in range(128):
                        if dp2[i + 1][or_val]:
                            dp2[i][or_val] = True
            if n - i >= k:
                for or_val in range(128):
                    dp2[i][or_val] = dp2[i][or_val] or dp2[i + 1][or_val]

        # Initialize masks and force_unsets
        mask1 = 0
        force_unset1 = 0
        mask2 = 0
        force_unset2 = 0
        result = 0

        # Iterate over each bit from 7th (most significant) to 0th (least significant)
        for b in range(7, -1, -1):
            bit = 1 << b
            option_a_possible = False
            option_b_possible = False

            # Option A: or1 has bit set, or2 has bit unset
            temp_mask1 = mask1 | bit
            temp_force_unset2 = force_unset2 | bit
            for i in range(k, n - k + 1):
                # Collect or1 values that satisfy mask1 and force_unset1, and have bit set
                or1_candidates = [or_val for or_val in range(128) if dp1[i][or_val] and (or_val & temp_mask1 == temp_mask1) and (or_val & force_unset1 == 0) and (or_val & bit != 0)]
                # Collect or2 values that satisfy mask2 and force_unset2, and have bit unset
                or2_candidates = [or_val for or_val in range(128) if dp2[i][or_val] and (or_val & mask2 == mask2) and (or_val & temp_force_unset2 == 0) and (or_val & bit == 0)]
                if or1_candidates and or2_candidates:
                    option_a_possible = True
                    break

            # Option B: or1 has bit unset, or2 has bit set
            temp_mask2 = mask2 | bit
            temp_force_unset1 = force_unset1 | bit
            for i in range(k, n - k + 1):
                # Collect or1 values that satisfy mask1 and force_unset1, and have bit unset
                or1_candidates = [or_val for or_val in range(128) if dp1[i][or_val] and (or_val & mask1 == mask1) and (or_val & temp_force_unset1 == 0) and (or_val & bit == 0)]
                # Collect or2 values that satisfy mask2 and force_unset2, and have bit set
                or2_candidates = [or_val for or_val in range(128) if dp2[i][or_val] and (or_val & temp_mask2 == temp_mask2) and (or_val & force_unset2 == 0) and (or_val & bit != 0)]
                if or1_candidates and or2_candidates:
                    option_b_possible = True
                    break

            # Set the bit in result if either option is possible
            if option_a_possible or option_b_possible:
                result |= bit
                # Update masks and force_unsets based on the chosen option
                if option_a_possible:
                    mask1 = temp_mask1
                    force_unset2 = temp_force_unset2
                else:
                    mask2 = temp_mask2
                    force_unset1 = temp_force_unset1
            else:
                # Update masks and force_unsets to maintain previous constraints
                mask1 |= bit if (mask1 & bit) else 0
                mask2 |= bit if (mask2 & bit) else 0
                force_unset1 |= bit if (force_unset1 & bit) else 0
                force_unset2 |= bit if (force_unset2 & bit) else 0

        return result

class Solution:
    def minStartingIndex(self, s: str, pattern: str) -> int:
        len_s = len(s)
        len_p = len(pattern)
        if len_p > len_s:
            return -1

        # Initialize mismatch count for the first window
        mismatches = 0
        for j in range(len_p):
            if s[j] != pattern[j]:
                mismatches += 1
        if mismatches <= 1:
            return 0

        # Slide the window from i=1 to i <= len_s - len_p
        for i in range(1, len_s - len_p + 1):
            # Remove the exitting character's mismatch status
            if s[i - 1] != pattern[0]:
                mismatches -= 1
            # Add the entering character's mismatch status
            if s[i + len_p - 1] != pattern[len_p - 1]:
                mismatches += 1
            if mismatches <= 1:
                return i
        return -1

import math
import itertools
import bisect

class Solution:
    def gcdValues(self, nums: List[int], queries: List[int]) -> List[int]:
        max_num = max(nums)
        freq = [0] * (max_num + 1)

        for num in nums:
            for i in range(1, int(math.isqrt(num)) + 1):
                if num % i == 0:
                    freq[i] += 1
                    if i != num // i:
                        freq[num // i] += 1

        count_pairs = [0] * (max_num + 1)
        for k in range(max_num, 0, -1):
            count_pairs[k] = math.comb(freq[k], 2)
            for m in range(2 * k, max_num + 1, k):
                count_pairs[k] -= count_pairs[m]

        unique_k = [k for k in range(1, max_num + 1) if count_pairs[k] > 0]
        unique_k.sort()
        cumulative = list(itertools.accumulate(count_pairs[k] for k in unique_k))

        answer = []
        for q in queries:
            idx = bisect.bisect_left(cumulative, q + 1)
            if idx < len(cumulative):
                answer.append(unique_k[idx])
            else:
                raise IndexError("Query index out of bounds")
        return answer

