class Solution:
    def validSequence(self, word1: str, word2: str) -> List[int]:
        # Precompute positions for each character in word1
        positions = {chr(c): [] for c in range(ord('a'), ord('z') + 1)}
        for i, char in enumerate(word1):
            positions[char].append(i)

        sequence = []
        changes = 0
        last_index = -1

        for char in word2:
            # Try to find the smallest index in positions[char] that is greater than last_index
            possible_indices = positions[char]
            idx = bisect.bisect_right(possible_indices, last_index)
            if idx < len(possible_indices):
                i = possible_indices[idx]
                sequence.append(i)
                last_index = i
            else:
                # If no match found and changes < 1, allow one change
                if changes == 0:
                    # Find the smallest i in word1 that is greater than last_index
                    i = last_index + 1
                    if i < len(word1):
                        sequence.append(i)
                        last_index = i
                        changes += 1
                    else:
                        return []
                else:
                    return []

        return sequence if changes <= 1 else []

class Solution:
    def kthCharacter(self, k: int) -> str:
        from math import ceil, log2

        def shift(char, offset):
            index = ord(char) - ord('a')
            shifted_index = (index + offset) % 26
            return chr(shifted_index + ord('a'))

        def get_kth(n, k):
            if n == 0:
                return 'a'
            length_half = 2 ** (n - 1)
            if k <= length_half:
                return get_kth(n - 1, k)
            else:
                char = get_kth(n - 1, k - length_half)
                return shift(char, 1)

        # Find the smallest n such that 2^n >= k
        n = ceil(log2(k)) if k > 1 else 0
        return get_kth(n, k)

class Solution:
    def minElement(self, nums: List[int]) -> int:
        def sum_digits(n):
            sum = 0
            while n > 0:
                sum += n % 10
                n = n // 10
            return sum
        return min(sum_digits(num) for num in nums)

import math

def mobius(b):
    if b == 1:
        return 1
    factors = 0
    i = 2
    while i * i <= b:
        if b % i == 0:
            factors += 1
            b //= i
            if b % i == 0:
                return 0
        else:
            i += 1
    if b > 1:
        factors += 1
    return 1 if factors % 2 == 0 else -1

def count_perfect_powers(N):
    if N == 1:
        return 1
    max_b = 1
    while (1 << max_b) <= N:
        max_b += 1
    count = 0
    for b in range(1, max_b + 1):
        mu_b = mobius(b)
        if mu_b == 0:
            continue
        root = N ** (1.0 / b)
        floored = math.floor(root)
        if b % 2 == 0:
            floored = floored if floored ** b <= N else floored - 1
        count += mu_b * floored
    return count

