def P(m):
    if m == 1:
        return 10
    k = m // 2
    if m % 2 == 0:
        return 9 * 10**(k - 1)
    else:
        return 9 * 10**k

def total_palindromes(m):
    if m <= 0:
        return 0
    total = 0
    for i in range(1, m):
        total += P(i)
    return total

def find_nth_palindrome(N):
    if N == 1:
        return '0'

    m = 1
    while True:
        if N <= total_palindromes(m):
            break
        m += 1

    N_th_m = N - total_palindromes(m - 1)
    h = (m + 1) // 2

    if h >= 1:
        a = 1 + (N_th_m - 1) // (10**(h - 1))
        b = (N_th_m - 1) % (10**(h - 1))
        first_h_digits = str(a) + format(b, '0{}d'.format(h - 1))
    else:
        a = N_th_m
        first_h_digits = str(a)

    if m % 2 == 0:
        second_half = first_h_digits[::-1]
    else:
        second_half = first_h_digits[:-1][::-1]

    full_palindrome = first_h_digits + second_half
    return full_palindrome

