def is_palindrome(s):
    return s == s[::-1]

def consists_of_digits_1_to_9(num):
    s = str(num)
    return all('1' <= c <= '9' for c in s)

def find_palindromic_sequence(N):
    if N == 1:
        return "1"
    s_N = str(N)
    if consists_of_digits_1_to_9(N) and is_palindrome(s_N):
        return s_N
    import math
    max_A = int(math.isqrt(N))
    for A in range(max_A, 0, -1):
        if N % (A * A) == 0:
            if consists_of_digits_1_to_9(A):
                M = N // (A * A)
                S_prime = find_palindromic_sequence(M)
                if S_prime != -1:
                    S = str(A) + "*" + S_prime + "*" + str(A)
                    if is_palindrome(S):
                        return S
    return -1

