def main():
    import sys
    from collections import defaultdict

    def gauss_elimination(A, M):
        n = len(A)
        m = len(A[0])
        pivot_cols = []
        for col in range(m):
            if len(pivot_cols) == M:
                break
            pivot_row = -1
            for row in range(n):
                if A[row][col] == 1 and all(A[row][p] == 0 for p in pivot_cols):
                    pivot_row = row
                    break
            if pivot_row == -1:
                continue
            pivot_cols.append(col)
            for row in range(n):
                if row != pivot_row and A[row][col] == 1:
                    for c in range(m):
                        A[row][c] ^= A[pivot_row][c]
        return pivot_cols

    N, M = map(int, sys.stdin.readline().split())
    edges = []
    for _ in range(M):
        u, v = map(int, sys.stdin.readline().split())
        edges.append((u-1, v-1))

    adj = defaultdict(list)
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    deg = {v: len(adj[v]) for v in range(N)}

    # Variables: X_v,b where v is vertex and b is bit (0 to 59)
    # Equation: for each v with deg[v] >= 1, and for each bit b, sum over u in adj[v] of X_u,b == 0

    num_vars = N * 60
    equations = []

    for v in range(N):
        if deg[v] >= 1:
            for b in range(60):
                eq = [0] * num_vars
                for u in adj[v]:
                    var_idx = u * 60 + b
                    eq[var_idx] = 1
                equations.append(eq)

    A = equations
    if not A:
        print("Yes")
        print(' '.join(['1'] * N))
        return

    pivot_cols = gauss_elimination(A, len(A))
    free_vars = [i for i in range(num_vars) if i not in pivot_cols]

    # Find a particular solution by setting free variables to 1
    X = [0] * num_vars
    for var in free_vars:
        X[var] = 1
    for row in range(len(A)):
        val = 0
        for col in range(num_vars):
            val ^= A[row][col] * X[col]
        if val != 0:
            # Adjust pivot variables to satisfy equations
            pivot_var = pivot_cols[row]
            X[pivot_var] ^= 1

    # Check if this solution makes any X_v zero
    X_v = [0] * N
    for v in range(N):
        for b in range(60):
            X_v[v] |= (X[v * 60 + b] << b)

    if all(X_v[v] != 0 for v in range(N)):
        print("Yes")
        print(' '.join(map(str, X_v)))
    else:
        print("No")

