MOD = 998244353

def main():
    import sys
    sys.setrecursionlimit(1 << 25)
    N, M = map(int, sys.stdin.read().split())
    if N == 0:
        print(0)
        return
    if M == 0:
        print(1)
        return

    # Step 1: Identify primes up to M
    primes = []
    for p in range(2, M + 1):
        is_prime = True
        for q in range(2, int(p**0.5) + 1):
            if p % q == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(p)

    # Step 2: Factorize numbers from 1 to M
    exponents = []
    for a in range(1, M + 1):
        exp = []
        b = a
        for p in primes:
            count = 0
            while b % p == 0:
                count += 1
                b //= p
            exp.append(count)
        exponents.append(exp)

    # Step 3: Define states
    max_exp = [0] * len(primes)
    for exp in exponents:
        for i in range(len(primes)):
            if exp[i] > max_exp[i]:
                max_exp[i] = exp[i]

    states = []
    from itertools import product
    for exp in product(*(range(e + 1) for e in max_exp)):
        states.append(exp)
    state_id = {state: i for i, state in enumerate(states)}

    # Step 4: Create transition matrix
    trans = [[0] * len(states) for _ in range(len(states))]
    for a in range(M):
        exp = exponents[a]
        for state in states:
            new_exp = tuple(min(e + exp[i], max_exp[i]) for i, e in enumerate(state))
            new_id = state_id[new_exp]
            trans[state_id[state]][new_id] += 1
            if trans[state_id[state]][new_id] >= MOD:
                trans[state_id[state]][new_id] -= MOD

    # Step 5: Matrix exponentiation
    def matmul(A, B):
        res = [[0] * len(B[0]) for _ in range(len(A))]
        for i in range(len(A)):
            for j in range(len(B[0])):
                for k in range(len(B)):
                    res[i][j] = (res[i][j] + A[i][k] * B[k][j]) % MOD
        return res

    def matpow(mat, exp):
        res = [[int(i == j) for j in range(len(mat))] for i in range(len(mat))]
        while exp:
            if exp & 1:
                res = matmul(res, mat)
            mat = matmul(mat, mat)
            exp >>= 1
        return res

    # Compute sum of matrices from M^1 to M^N
    if N == 1:
        sum_mat = trans
    else:
        M_I = matmul(trans, [[int(i == j) for j in range(len(trans))] for i in range(len(trans))])
        M_N = matpow(trans, N)
        M_1_to_N = matmul(M_N, trans)
        sum_mat = matmul(M_1_to_N, [[1] * len(trans)] * len(trans))

    # Step 6: Compute the sum of scores
    total = 0
    for i in range(len(states)):
        state = states[i]
        score = 1
        for e in state:
            score = (score * (e + 1)) % MOD
        total = (total + sum_mat[0][i] * score) % MOD

    print(total)

