def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    M = int(data[1])
    A = list(map(int, data[2:2+N]))
    B = list(map(int, data[2+N:2+2*N]))

    total_ops = 0
    for i in range(N):
        if A[i] == B[i]:
            continue  # No operation needed

        # Forbidden values are A[i-1] and A[i+1]
        forbidden = set()
        if i > 0:
            forbidden.add(A[i-1])
        if i < N-1:
            forbidden.add(A[i+1])

        # Calculate distances
        d1 = (B[i] - A[i]) % M  # Clockwise
        d2 = (M - d1) % M       # Counterclockwise

        # Check if path is valid
        path1_valid = True
        path2_valid = True

        if B[i] > A[i]:
            # Clockwise path: A[i] < X < B[i]
            for F in forbidden:
                if A[i] < F < B[i]:
                    path1_valid = False
                    break
            # Counterclockwise path: X > A[i] or X < B[i]
            for F in forbidden:
                if (F > A[i]) or (F < B[i]):
                    path2_valid = False
                    break
        else:
            # Clockwise path: X > A[i] or X < B[i]
            for F in forbidden:
                if F > A[i] or F < B[i]:
                    path1_valid = False
                    break
            # Counterclockwise path: B[i] < X < A[i]
            for F in forbidden:
                if B[i] < F < A[i]:
                    path2_valid = False
                    break

        if path1_valid and path2_valid:
            total_ops += min(d1, d2)
        elif path1_valid:
            total_ops += d1
        elif path2_valid:
            total_ops += d2
        else:
            print(-1)
            return

    print(total_ops)

